/* FORCE HIDE HEADER ON SCROLL – Jupiter Override */
.page-id-71131 body:not(.at-top) #page-header,
.page-id-73489 body:not(.at-top) #page-header {
    transform: translateY(-110%) !important;
}

/* Visible only at top */
